// src/api/notificationDispatchApi.ts
const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface NotificationDispatch {
  notificationDispatchId: number;
  companyId: number;
  sourceType: string;
  sourceId: number;
  recipientType: string;
  recipientId: number;
  eventName: string;
  preferredChannel: string;
  selectedChannel: string;
  attemptedChannels: string; // JSON string
  fallbackReason?: string;
  status: string;
  providerMessageId?: string;
  providerName?: string;
  messagePreview?: string;
  sentAt?: string;
  confirmedAt?: string;
  failedAt?: string;
  created_At: string;
  updated_at?: string;
  active: boolean;
}

export interface NotificationDispatchListResponse {
  notificationDispatchs: NotificationDispatch[];
}

// Custom API response for the /dispatch endpoint if it returns a single item
export interface NotificationDispatchApiResponse {
  notificationDispatchs: NotificationDispatch[];
  // If the /dispatch endpoint returns a single object directly,
  // we might need a separate interface or handle it.
  // Assuming it also wraps in 'notificationDispatchs' array for consistency with SPs.
}

// GET ALL — POST /all_notificationDispatchs
export async function getAllNotificationDispatchs(companyId: number, filters: Record<string, unknown> = {}): Promise<NotificationDispatch[]> {
  const res = await fetch(BASE_URL + "/all_notificationDispatchs", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "notificationDispatchs": [{ "companyId": companyId, ...filters }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: NotificationDispatchListResponse = await res.json();
  return data.notificationDispatchs ?? [];
}

// CREATE — action: 1 (via sp_notificationDispatchs)
export async function createNotificationDispatch(payload: Omit<NotificationDispatch, "notificationDispatchId" | "created_At" | "active">): Promise<NotificationDispatch> {
  const res = await fetch(BASE_URL + "/notificationDispatchs", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "notificationDispatchs": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: NotificationDispatchListResponse = await res.json();
  return data.notificationDispatchs[0];
}

// UPDATE — action: 2 (via sp_notificationDispatchs)
export async function updateNotificationDispatch(id: number, payload: Partial<NotificationDispatch>): Promise<NotificationDispatch> {
  const res = await fetch(BASE_URL + "/notificationDispatchs", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "notificationDispatchs": [{ "action": 2, "notificationDispatchId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: NotificationDispatchListResponse = await res.json();
  return data.notificationDispatchs[0];
}

// DELETE — action: 3 (via sp_notificationDispatchs)
export async function deleteNotificationDispatch(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/notificationDispatchs", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "notificationDispatchs": [{ "action": 3, "notificationDispatchId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}

// GET ONE — POST /one_notificationDispatchs
export async function getOneNotificationDispatch(id: number, companyId: number): Promise<NotificationDispatch | null> {
  const res = await fetch(BASE_URL + "/one_notificationDispatchs", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "notificationDispatchs": [{ "notificationDispatchId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: NotificationDispatchListResponse = await res.json();
  return data.notificationDispatchs?.[0] || null;
}

// CONNECTOR ENDPOINTS

export interface DispatchNotificationPayload {
  companyId: number;
  sourceType: string;
  sourceId: number;
  recipientType: string;
  recipientId: number;
  eventName: string;
  messagePreview?: string;
}

export interface ConfirmNotificationPayload {
  providerMessageId: string;
  status: string; // e.g., 'delivered', 'read', 'undelivered'
  outcome?: string; // Additional outcome from provider
  timestamp?: string;
  companyId: number;
}

// POST /api/notificationDispatch/dispatch
export async function dispatchNotification(payload: DispatchNotificationPayload): Promise<NotificationDispatchApiResponse> {
  const res = await fetch(BASE_URL + "/api/notificationDispatch/dispatch", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// POST /api/notificationDispatch/confirm
export async function confirmNotificationDelivery(payload: ConfirmNotificationPayload): Promise<NotificationDispatchApiResponse> {
  const res = await fetch(BASE_URL + "/api/notificationDispatch/confirm", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}
