// src/pages/NotificationDispatchPage.tsx
import React, { useState, useEffect, useRef } from 'react';
import {
  IonPage,
  IonContent,
  IonList,
  IonItem,
  IonLabel,
  IonText,
  IonBadge,
  IonSpinner,
  IonToast,
  IonLoading,
  IonInfiniteScroll,
  IonInfiniteScrollContent,
  IonSelect,
  IonSelectOption,
  IonModal,
  IonCard,
  IonCardHeader,
  IonCardTitle,
  IonCardContent,
  IonToolbar,
  IonButtons,
  IonButton,
  IonIcon
} from '@ionic/react';
import { ellipsisHorizontal, closeCircleOutline, checkmarkCircleOutline, informationCircleOutline, chevronForward, chevronBack, close } from 'ionicons/icons';
import { useUser } from '../components/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import {
  NotificationDispatch,
  getAllNotificationDispatchs,
  getOneNotificationDispatch,
} from '../api/notificationDispatchApi';
import './NotificationDispatchPage.css';

// UTC-7 conversion
const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString('es-MX', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });
};

const NotificationDispatchPage: React.FC = () => {
  const { companyId } = useUser();

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [dispatches, setDispatches] = useState<NotificationDispatch[]>([]);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const PAGE_SIZE = 20;

  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedDispatch, setSelectedDispatch] = useState<NotificationDispatch | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailError, setDetailError] = useState('');

  const [filterSourceType, setFilterSourceType] = useState<string>('');
  const [filterEventName, setFilterEventName] = useState<string>('');
  const [filterStatus, setFilterStatus] = useState<string>('');
  const [filterSelectedChannel, setFilterSelectedChannel] = useState<string>('');

  const [showCostSummaryModal, setShowCostSummaryModal] = useState(false);
  const [costSummaryData, setCostSummaryData] = useState<any>(null); // Replace 'any' with a proper interface for cost summary

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchDispatches = async (currentPage: number, append: boolean = false) => {
    if (!companyId) return;

    setLoading(true);
    setError('');
    try {
      const filters: Record<string, unknown> = {
        offset: currentPage * PAGE_SIZE,
        limit: PAGE_SIZE,
        companyId: companyId,
      };
      if (filterSourceType) filters.sourceType = filterSourceType;
      if (filterEventName) filters.eventName = filterEventName;
      if (filterStatus) filters.status = filterStatus;
      if (filterSelectedChannel) filters.selectedChannel = filterSelectedChannel;

      const newDispatches = await getAllNotificationDispatchs(companyId, filters);

      setDispatches((prev) => (append ? [...prev, ...newDispatches] : newDispatches));
      setHasMore(newDispatches.length === PAGE_SIZE);
      setPage(currentPage);
    } catch (err) {
      setError((err as Error).message ?? 'Error loading notification dispatches.');
    } finally {
      setLoading(false);
    }
  };

  const loadMoreItems = async (ev: CustomEvent<void>) => {
    if (hasMore && !loading) {
      await fetchDispatches(page + 1, true);
    }
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleOpenDetailModal = async (dispatchId: number) => {
    if (!companyId) return;
    setDetailLoading(true);
    setDetailError('');
    setShowDetailModal(true);
    try {
      const dispatch = await getOneNotificationDispatch(dispatchId, companyId);
      setSelectedDispatch(dispatch);
    } catch (err) {
      setDetailError((err as Error).message ?? 'Error loading dispatch details.');
      setSelectedDispatch(null);
    } finally {
      setDetailLoading(false);
    }
  };

  const handleOpenCostSummaryModal = async () => {
    if (!companyId) return;
    // In a real scenario, this would fetch data for the ChannelCostSummaryCard
    // For now, use dummy data.
    setCostSummaryData({
      dateRange: "Last 30 days",
      pushPercent: 75,
      whatsappPercent: 20,
      smsPercent: 5,
      estimatedSmsCostAvoided: 1250.75
    });
    setShowCostSummaryModal(true);
  };

  useEffect(() => {
    fetchDispatches(0);
  }, [companyId, filterSourceType, filterEventName, filterStatus, filterSelectedChannel]);

  // Refetch on view re-enter
  // useIonViewWillEnter(() => {
  //   fetchDispatches(0);
  // }, [companyId, filterSourceType, filterEventName, filterStatus, filterSelectedChannel]);

  const renderDispatchLogFeedStep = () => (
    <div className="dispatch-log-feed-step">
      <div className="dispatch-filters">
        <IonSelect
          label="Source Type"
          labelPlacement="floating"
          fill="outline"
          value={filterSourceType}
          onIonChange={(e: CustomEvent<any>) => setFilterSourceType(e.detail.value)}
        >
          <IonSelectOption value="">All</IonSelectOption>
          <IonSelectOption value="income">Income</IonSelectOption>
          <IonSelectOption value="expense">Expense</IonSelectOption>
          <IonSelectOption value="ticket">Ticket</IonSelectOption>
        </IonSelect>
        <IonSelect
          label="Event Name"
          labelPlacement="floating"
          fill="outline"
          value={filterEventName}
          onIonChange={(e: CustomEvent<any>) => setFilterEventName(e.detail.value)}
        >
          <IonSelectOption value="">All</IonSelectOption>
          <IonSelectOption value="income_created">Income Created</IonSelectOption>
          <IonSelectOption value="expense_created">Expense Created</IonSelectOption>
          <IonSelectOption value="ticket_ready">Ticket Ready</IonSelectOption>
        </IonSelect>
        <IonSelect
          label="Status"
          labelPlacement="floating"
          fill="outline"
          value={filterStatus}
          onIonChange={(e: CustomEvent<any>) => setFilterStatus(e.detail.value)}
        >
          <IonSelectOption value="">All</IonSelectOption>
          <IonSelectOption value="pending">Pending</IonSelectOption>
          <IonSelectOption value="sent">Sent</IonSelectOption>
          <IonSelectOption value="confirmed">Confirmed</IonSelectOption>
          <IonSelectOption value="failed">Failed</IonSelectOption>
        </IonSelect>
        <IonSelect
          label="Channel"
          labelPlacement="floating"
          fill="outline"
          value={filterSelectedChannel}
          onIonChange={(e: CustomEvent<any>) => setFilterSelectedChannel(e.detail.value)}
        >
          <IonSelectOption value="">All</IonSelectOption>
          <IonSelectOption value="push">Push</IonSelectOption>
          <IonSelectOption value="whatsapp">WhatsApp</IonSelectOption>
          <IonSelectOption value="sms">SMS</IonSelectOption>
        </IonSelect>
      </div>

      <IonList className="dispatch-list">
        {dispatches.map((dispatch) => (
          <IonItem button key={dispatch.notificationDispatchId} onClick={() => handleOpenDetailModal(dispatch.notificationDispatchId)}>
            <div className="dispatch-item-content">
              <IonLabel>
                <IonText color="dark">
                  <h2>{dispatch.eventName} ({dispatch.sourceType}:{dispatch.sourceId})</h2>
                </IonText>
                <p>Recipient: {dispatch.recipientType}:{dispatch.recipientId}</p>
                <p><small>{toHermosillo(dispatch.created_At)}</small></p>
              </IonLabel>
              <div className="dispatch-item-badges">
                <IonBadge className={`dispatch-channel-badge channel-${dispatch.selectedChannel}`}>
                  {dispatch.selectedChannel}
                </IonBadge>
                <IonBadge className={`dispatch-status-badge status-${dispatch.status}`}>
                  {dispatch.status}
                </IonBadge>
              </div>
              <IonIcon icon={chevronForward} slot="end" />
            </div>
          </IonItem>
        ))}
      </IonList>

      <IonInfiniteScroll onIonInfinite={loadMoreItems} threshold="100px" disabled={!hasMore || loading}>
        <IonInfiniteScrollContent loadingSpinner="dots" loadingText="Loading more dispatches..." />
      </IonInfiniteScroll>
    </div>
  );

  const renderDispatchDetailModal = () => (
    <IonModal isOpen={showDetailModal} onDidDismiss={() => setShowDetailModal(false)} className="dispatch-detail-modal">
      <IonHeader>
        <IonToolbar>
          <IonTitle>Dispatch Details</IonTitle>
          <IonButtons slot="end">
            <IonButton onClick={() => setShowDetailModal(false)}>
              <IonIcon icon={close} />
            </IonButton>
          </IonButtons>
        </IonToolbar>
      </IonHeader>
      <IonContent className="ion-padding">
        {detailLoading && <IonSpinner name="dots" />}
        {detailError && <IonText color="danger">{detailError}</IonText>}
        {selectedDispatch && (
          <IonList>
            <IonItem>
              <IonLabel>Notification ID</IonLabel>
              <IonText slot="end">{selectedDispatch.notificationDispatchId}</IonText>
            </IonItem>
            <IonItem>
              <IonLabel>Source</IonLabel>
              <IonText slot="end">{selectedDispatch.sourceType}:{selectedDispatch.sourceId}</IonText>
            </IonItem>
            <IonItem>
              <IonLabel>Recipient</IonLabel>
              <IonText slot="end">{selectedDispatch.recipientType}:{selectedDispatch.recipientId}</IonText>
            </IonItem>
            <IonItem>
              <IonLabel>Event Name</IonLabel>
              <IonText slot="end">{selectedDispatch.eventName}</IonText>
            </IonItem>
            <IonItem>
              <IonLabel>Preferred Channel</IonLabel>
              <IonBadge className={`dispatch-channel-badge channel-${selectedDispatch.preferredChannel}`}>
                {selectedDispatch.preferredChannel}
              </IonBadge>
            </IonItem>
            <IonItem>
              <IonLabel>Selected Channel</IonLabel>
              <IonBadge className={`dispatch-channel-badge channel-${selectedDispatch.selectedChannel}`}>
                {selectedDispatch.selectedChannel}
              </IonBadge>
            </IonItem>
            <IonItem>
              <IonLabel>Status</IonLabel>
              <IonBadge className={`dispatch-status-badge status-${selectedDispatch.status}`}>
                {selectedDispatch.status}
              </IonBadge>
            </IonItem>
            {selectedDispatch.fallbackReason && (
              <IonItem>
                <IonLabel>Fallback Reason</IonLabel>
                <IonText slot="end">{selectedDispatch.fallbackReason}</IonText>
              </IonItem>
            )}
            {selectedDispatch.messagePreview && (
              <IonItem>
                <IonLabel>Message Preview</IonLabel>
                <IonText slot="end">{selectedDispatch.messagePreview}</IonText>
              </IonItem>
            )}
            {selectedDispatch.providerName && (
              <IonItem>
                <IonLabel>Provider</IonLabel>
                <IonText slot="end">{selectedDispatch.providerName}</IonText>
              </IonItem>
            )}
            {selectedDispatch.providerMessageId && (
              <IonItem>
                <IonLabel>Provider Message ID</IonLabel>
                <IonText slot="end">{selectedDispatch.providerMessageId}</IonText>
              </IonItem>
            )}
            {selectedDispatch.sentAt && (
              <IonItem>
                <IonLabel>Sent At</IonLabel>
                <IonText slot="end">{toHermosillo(selectedDispatch.sentAt)}</IonText>
              </IonItem>
            )}
            {selectedDispatch.confirmedAt && (
              <IonItem>
                <IonLabel>Confirmed At</IonLabel>
                <IonText slot="end">{toHermosillo(selectedDispatch.confirmedAt)}</IonText>
              </IonItem>
            )}
            {selectedDispatch.failedAt && (
              <IonItem>
                <IonLabel>Failed At</IonLabel>
                <IonText slot="end">{toHermosillo(selectedDispatch.failedAt)}</IonText>
              </IonItem>
            )}
            <IonItem>
              <IonLabel>Created At</IonLabel>
              <IonText slot="end">{toHermosillo(selectedDispatch.created_At)}</IonText>
            </IonItem>
            {selectedDispatch.updated_at && (
              <IonItem>
                <IonLabel>Last Updated</IonLabel>
                <IonText slot="end">{toHermosillo(selectedDispatch.updated_at)}</IonText>
              </IonItem>
            )}

            <IonCard className="attempted-channels-card">
              <IonCardHeader>
                <IonCardTitle>Attempt History</IonCardTitle>
              </IonCardHeader>
              <IonCardContent>
                {selectedDispatch.attemptedChannels && JSON.parse(selectedDispatch.attemptedChannels).length > 0 ? (
                  <IonList lines="none">
                    {JSON.parse(selectedDispatch.attemptedChannels).map((attempt: any, index: number) => (
                      <IonItem key={index} className="attempt-item">
                        <IonIcon
                          icon={
                            attempt.outcome.includes('SENT') || attempt.outcome.includes('DELIVERED') || attempt.outcome.includes('CONFIRMED')
                              ? checkmarkCircleOutline
                              : attempt.outcome.includes('FAILED') || attempt.outcome.includes('REJECTED') || attempt.outcome.includes('UNAVAILABLE') || attempt.outcome.includes('TIMEOUT')
                                ? closeCircleOutline
                                : informationCircleOutline
                          }
                          slot="start"
                          color={
                            attempt.outcome.includes('SENT') || attempt.outcome.includes('DELIVERED') || attempt.outcome.includes('CONFIRMED')
                              ? 'success'
                              : attempt.outcome.includes('FAILED') || attempt.outcome.includes('REJECTED') || attempt.outcome.includes('UNAVAILABLE') || attempt.outcome.includes('TIMEOUT')
                                ? 'danger'
                                : 'medium'
                          }
                        />
                        <IonLabel>
                          <h3>Channel: {attempt.channel}</h3>
                          <p>Outcome: {attempt.outcome}</p>
                          <p><small>Timestamp: {toHermosillo(attempt.timestamp)}</small></p>
                        </IonLabel>
                      </IonItem>
                    ))}
                  </IonList>
                ) : (
                  <IonText>No attempt history available.</IonText>
                )}
              </IonCardContent>
            </IonCard>
          </IonList>
        )}
      </IonContent>
    </IonModal>
  );

  const renderChannelCostSummaryCard = () => (
    <IonModal isOpen={showCostSummaryModal} onDidDismiss={() => setShowCostSummaryModal(false)} className="cost-summary-modal">
      <IonHeader>
        <IonToolbar>
          <IonTitle>Channel Cost Summary</IonTitle>
          <IonButtons slot="end">
            <IonButton onClick={() => setShowCostSummaryModal(false)}>
              <IonIcon icon={close} />
            </IonButton>
          </IonButtons>
        </IonToolbar>
      </IonHeader>
      <IonContent className="ion-padding">
        {costSummaryData ? (
          <IonCard className="channel-cost-summary-card">
            <IonCardHeader>
              <IonCardTitle>Dispatch Channel Breakdown</IonCardTitle>
              <IonText color="medium"><small>For {costSummaryData.dateRange}</small></IonText>
            </IonCardHeader>
            <IonCardContent>
              <IonList lines="full">
                <IonItem>
                  <IonLabel>Push Dispatches</IonLabel>
                  <IonText slot="end" color="primary">{costSummaryData.pushPercent}%</IonText>
                </IonItem>
                <IonItem>
                  <IonLabel>WhatsApp Dispatches</IonLabel>
                  <IonText slot="end" color="success">{costSummaryData.whatsappPercent}%</IonText>
                </IonItem>
                <IonItem>
                  <IonLabel>SMS Dispatches</IonLabel>
                  <IonText slot="end" color="warning">{costSummaryData.smsPercent}%</IonText>
                </IonItem>
                <IonItem>
                  <IonLabel>Estimated SMS Cost Avoided</IonLabel>
                  <IonText slot="end" color="success">${costSummaryData.estimatedSmsCostAvoided.toFixed(2)}</IonText>
                </IonItem>
              </IonList>
            </IonCardContent>
          </IonCard>
        ) : (
          <IonText>No cost summary data available.</IonText>
        )}
      </IonContent>
    </IonModal>
  );

  return (
    <IonPage className="notification-dispatch-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Notification Dispatch Log — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message="Loading dispatches..." />
        <IonToast isOpen={!!error} message={error} duration={3000} onDidDismiss={() => setError('')} color="danger" />

        <IonButton expand="block" onClick={handleOpenCostSummaryModal} className="ion-margin-bottom">
          View Channel Cost Summary
        </IonButton>

        {renderDispatchLogFeedStep()}
        {renderDispatchDetailModal()}
        {renderChannelCostSummaryCard()}
      </IonContent>
    </IonPage>
  );
};

export default NotificationDispatchPage;
