edDispatch.updated_at && (\n              <IonItem>\n                <IonLabel>Last Updated</IonLabel>\n                <IonText slot=\"end\">{toHermosillo(selectedDispatch.updated_at)}</IonText>\n              </IonItem>\n            )}\n\n            <IonCard className=\"attempted-channels-card\">\n              <IonCardHeader>\n                <IonCardTitle>Attempt History</IonCardTitle>\n              </IonCardHeader>\n              <IonCardContent>\n                {selectedDispatch.attemptedChannels && JSON.parse(selectedDispatch.attemptedChannels).length > 0 ? (\n                  <IonList lines=\"none\">\n                    {JSON.parse(selectedDispatch.attemptedChannels).map((attempt: any, index: number) => (\n                      <IonItem key={index} className=\"attempt-item\">\n                        <IonIcon\n                          icon={\n                            attempt.outcome.includes('SENT') || attempt.outcome.includes('DELIVERED') || attempt.outcome.includes('CONFIRMED')\n                              ? checkmarkCircleOutline\n                              : attempt.outcome.includes('FAILED') || attempt.outcome.includes('REJECTED') || attempt.outcome.includes('UNAVAILABLE') || attempt.outcome.includes('TIMEOUT')\n                                ? closeCircleOutline\n                                : informationCircleOutline\n                          }\n                          slot=\"start\"\n                          color={\n                            attempt.outcome.includes('SENT') || attempt.outcome.includes('DELIVERED') || attempt.outcome.includes('CONFIRMED')\n                              ? 'success'\n                              : attempt.outcome.includes('FAILED') || attempt.outcome.includes('REJECTED') || attempt.outcome.includes('UNAVAILABLE') || attempt.outcome.includes('TIMEOUT')\n                                ? 'danger'\n                                : 'medium'\n                          }\n                        />\n                        <IonLabel>\n                          <h3>Channel: {attempt.channel}</h3>\n                          <p>Outcome: {attempt.outcome}</p>\n                          <p><small>Timestamp: {toHermosillo(attempt.timestamp)}</small></p>\n                        </IonLabel>\n                      </IonItem>\n                    ))}\n                  </IonList>\n                ) : (\n                  <IonText>No attempt history available.</IonText>\n                )}\n              </IonCardContent>\n            </IonCard>\n          </IonList>\n        )}\n      </IonContent>\n    </IonModal>\n  );\n\n  const renderChannelCostSummaryCard = () => (\n    <IonModal isOpen={showCostSummaryModal} onDidDismiss={() => setShowCostSummaryModal(false)} className=\"cost-summary-modal\">\n      <IonHeader>\n        <IonToolbar>\n          <IonTitle>Channel Cost Summary</IonTitle>\n          <IonButtons slot=\"end\">\n            <IonButton onClick={() => setShowCostSummaryModal(false)}>\n              <IonIcon icon={close} />\n            </IonButton>\n          </IonButtons>\n        </IonToolbar>\n      </IonHeader>\n      <IonContent className=\"ion-padding\">\n        {costSummaryData ? (\n          <IonCard className=\"channel-cost-summary-card\">\n            <IonCardHeader>\n              <IonCardTitle>Dispatch Channel Breakdown</IonCardTitle>\n              <IonText color=\"medium\"><small>For {costSummaryData.dateRange}</small></IonText>\n            </IonCardHeader>\n            <IonCardContent>\n              <IonList lines=\"full\">\n                <IonItem>\n                  <IonLabel>Push Dispatches</IonLabel>\n                  <IonText slot=\"end\" color=\"primary\">{costSummaryData.pushPercent}%</IonText>\n                </IonItem>\n                <IonItem>\n                  <IonLabel>WhatsApp Dispatches</IonLabel>\n                  <IonText slot=\"end\" color=\"success\">{costSummaryData.whatsappPercent}%</IonText>\n                </IonItem>\n                <IonItem>\n                  <IonLabel>SMS Dispatches</IonLabel>\n                  <IonText slot=\"end\" color=\"warning\">{costSummaryData.smsPercent}%</IonText>\n                </IonItem>\n                <IonItem>\n                  <IonLabel>Estimated SMS Cost Avoided</IonLabel>\n                  <IonText slot=\"end\" color=\"success\">${costSummaryData.estimatedSmsCostAvoided.toFixed(2)}</IonText>\n                </IonItem>\n              </IonList>\n            </IonCardContent>\n          </IonCard>\n        ) : (\n          <IonText>No cost summary data available.</IonText>\n        )}\n      </IonContent>\n    </IonModal>\n  );\n\n  return (\n    <IonPage className=\"notification-dispatch-page\">\n      <Header\n        presentAlertPopover={presentAlertPopover}\n        presentMailPopover={presentMailPopover}\n        screenTitle=\"Notification Dispatch Log — POS GMO\"\n      />\n      <AlertPopover\n        isOpen={popoverState.showAlertPopover}\n        event={popoverState.event}\n        onDidDismiss={dismissAlertPopover}\n      />\n      <MailPopover\n        isOpen={popoverState.showMailPopover}\n        event={popoverState.event}\n        onDidDismiss={dismissMailPopover}\n      />\n\n      <IonContent fullscreen className=\"ion-padding\">\n        <IonLoading isOpen={loading} message=\"Loading dispatches...\" />\n        <IonToast isOpen={!!error} message={error} duration={3000} onDidDismiss={() => setError('')} color=\"danger\" />\n\n        <IonButton expand=\"block\" onClick={handleOpenCostSummaryModal} className=\"ion-margin-bottom\">\n          View Channel Cost Summary\n        </IonButton>\n\n        {renderDispatchLogFeedStep()}\n        {renderDispatchDetailModal()}\n        {renderChannelCostSummaryCard()}\n      </IonContent>\n    </IonPage>\n  );\n};\n\nexport default NotificationDispatchPage;\n"
